#include "viewer.h"
#include <stdlib.h>
#include <wchar.h>
#include <string.h>

wchar_t *dupw(const wchar_t *s) { if(!s)return NULL; size_t n=wcslen(s)+1; wchar_t *p=malloc(n*sizeof(*p)); if(p)memcpy(p,s,n*sizeof(*p)); return p; }
static wchar_t *join(const wchar_t *a,const wchar_t *b){size_t x=wcslen(a),y=wcslen(b); BOOL slash=x&&a[x-1]!=L'\\'; wchar_t *p=malloc((x+y+slash+1)*sizeof(wchar_t)); if(!p)return NULL; memcpy(p,a,x*sizeof(wchar_t)); if(slash)p[x++]=L'\\'; memcpy(p+x,b,(y+1)*sizeof(wchar_t)); return p;}
void files_close(FileList *f){if(!f)return; for(size_t i=0;i<f->count;i++){free(f->items[i].path);free(f->items[i].name);}free(f->items);free(f->directory);memset(f,0,sizeof(*f));}
static BOOL push(FileList *f,const wchar_t *dir,const WIN32_FIND_DATAW *d){if(f->count==f->capacity){size_t n=f->capacity?f->capacity*2:64;if(n>SIZE_MAX/sizeof(FileEntry))return FALSE;FileEntry *q=realloc(f->items,n*sizeof(*q));if(!q)return FALSE;f->items=q;f->capacity=n;}FileEntry e={0};e.path=join(dir,d->cFileName);e.name=dupw(d->cFileName);if(!e.path||!e.name){free(e.path);free(e.name);return FALSE;}e.modified=d->ftLastWriteTime;e.size=((ULONGLONG)d->nFileSizeHigh<<32)|d->nFileSizeLow;f->items[f->count++]=e;return TRUE;}
static BOOL valid(const wchar_t *name){static const wchar_t *exts[]={L".jpg",L".jpeg",L".jpe",L".png",L".bmp",L".dib",L".gif",L".tif",L".tiff",L".ico",L".webp",L".heic",L".heif",L".avif"};const wchar_t *p=wcsrchr(name,L'.');if(!p)return FALSE;for(size_t i=0;i<sizeof(exts)/sizeof(exts[0]);i++)if(_wcsicmp(p,exts[i])==0)return TRUE;return FALSE;}
static SortMode sortMode;static BOOL reverseSort;
static int compare(const void *pa,const void *pb){const FileEntry *a=pa,*b=pb;int r=0;switch(sortMode){case SORT_NATURAL:r=StrCmpLogicalW(a->name,b->name);break;case SORT_NAME:r=CompareStringOrdinal(a->name,-1,b->name,-1,TRUE)-CSTR_EQUAL;break;case SORT_DATE:r=CompareFileTime(&a->modified,&b->modified);break;case SORT_SIZE:r=(a->size>b->size)-(a->size<b->size);break;}if(r==0)r=CompareStringOrdinal(a->name,-1,b->name,-1,FALSE)-CSTR_EQUAL;if(r==0)r=wcscmp(a->path,b->path);return reverseSort?-r:r;}
static BOOL enumerate(FileList *f,const wchar_t *directory){wchar_t *pattern=join(directory,L"*");if(!pattern)return FALSE;WIN32_FIND_DATAW fd;HANDLE h=FindFirstFileW(pattern,&fd);free(pattern);if(h==INVALID_HANDLE_VALUE)return FALSE;BOOL ok=TRUE;do {if(!(fd.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)&&valid(fd.cFileName)){if(!push(f,directory,&fd)){ok=FALSE;break;}}}while(FindNextFileW(h,&fd));FindClose(h);return ok;}
BOOL files_directory_first(wchar_t **first,const wchar_t *directory){*first=NULL;FileList f={0};if(!enumerate(&f,directory)){files_close(&f);return FALSE;}sortMode=SORT_NATURAL;reverseSort=FALSE;qsort(f.items,f.count,sizeof(FileEntry),compare);if(f.count)*first=dupw(f.items[0].path);files_close(&f);return *first!=NULL;}
BOOL files_open(FileList *f,const wchar_t *filepath,SortMode mode,BOOL descending){wchar_t *path=NULL;DWORD n=GetFullPathNameW(filepath,0,NULL,NULL);if(!n||n>32760)return FALSE;path=malloc((size_t)(n+1)*sizeof(wchar_t));if(!path)return FALSE;if(!GetFullPathNameW(filepath,n+1,path,NULL)){free(path);return FALSE;}wchar_t *last=wcsrchr(path,L'\\');if(!last){free(path);return FALSE;}wchar_t *dir=dupw(path);if(!dir){free(path);return FALSE;}dir[last-path+(last==path?1:0)]=L'\0';FileList temp={0};temp.directory=dir;if(!enumerate(&temp,dir)){files_close(&temp);free(path);return FALSE;}sortMode=mode;reverseSort=descending;qsort(temp.items,temp.count,sizeof(FileEntry),compare);temp.index=SIZE_MAX;for(size_t i=0;i<temp.count;i++)if(_wcsicmp(temp.items[i].path,path)==0){temp.index=i;break;}free(path);if(temp.index==SIZE_MAX){files_close(&temp);return FALSE;}files_close(f);*f=temp;return TRUE;}
